        ts:    'typescript',
        py:    'python',
        rb:    'ruby',
        cs:    'csharp',
        sh:    'bash',
        shell: 'bash',
        yml:   'yaml',
        md:    'markdown',
        htm:   'xml',       // hljs xml grammar lives in xml.min.js; registered as 'html'
