        value         : 0,
        color         : 'primary',
        striped       : false,
        animated      : false,
        indeterminate : false,
        label         : false,
        labelFormat   : '{value}%',
        duration      : 1200,
        easing        : 'cubic-bezier(0.4, 0, 0.2, 1)',
        size          : '',
